def generate_dataset():
    dataset = []
    idx = 1

    # 1. English cases (75)
    for cat, text, norm in ENGLISH_COMPLAINTS[:75]:
        dataset.append({
            "id": f"EVAL-{idx:04d}",
            "category": cat,
            "original_text": text,
            "expected_language": "en",
            "expected_script": "latin",
            "is_code_mixed": False,
            "expected_normalized_text": norm,
            "expected_translation_en": norm,
        })
        idx += 1

    # 2. Marathi Devanagari cases (75)
    for cat, text, norm in MARATHI_COMPLAINTS[:75]:
        dataset.append({
            "id": f"EVAL-{idx:04d}",
            "category": cat,
            "original_text": text,
            "expected_language": "mr",
            "expected_script": "devanagari",
            "is_code_mixed": False,
            "expected_normalized_text": norm,
            "expected_translation_en": None,
        })
        idx += 1

    # 3. Hindi Devanagari cases (75)
    for cat, text, norm in HINDI_COMPLAINTS[:75]:
        dataset.append({
            "id": f"EVAL-{idx:04d}",
            "category": cat,
            "original_text": text,
            "expected_language": "hi",
            "expected_script": "devanagari",
            "is_code_mixed": False,
            "expected_normalized_text": norm,
            "expected_translation_en": None,
        })
        idx += 1

    # 4. Code-mixed / Romanized cases (75)
    for cat, text, norm in CODE_MIXED_COMPLAINTS[:75]:
        dataset.append({
            "id": f"EVAL-{idx:04d}",
            "category": cat,
            "original_text": text,
            "expected_language": "mr-en",
            "expected_script": "latin",
            "is_code_mixed": True,
            "expected_normalized_text": norm,
            "expected_translation_en": None,
        })
        idx += 1

    DEST_PATH.parent.mkdir(parents=True, exist_ok=True)
    with open(DEST_PATH, "w", encoding="utf-8") as f:
        json.dump(dataset, f, ensure_ascii=False, indent=2)

    print(f"Successfully generated {len(dataset)} evaluation cases in {DEST_PATH}")


if __name__ == "__main__":
    generate_dataset()
